import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.BTt0kA_k.js";const s="/RelayPulse/screenshots/user/records-list.webp",i="/RelayPulse/screenshots/user/record-error.webp",d="/RelayPulse/screenshots/user/records-tokens.webp",_=JSON.parse('{"title":"探测记录与 Token 统计","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/records.md","filePath":"user/use/records.md"}'),l={name:"user/use/records.md"};function n(c,e,p,u,h,f){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="探测记录与-token-统计" tabindex="-1">探测记录与 Token 统计 <a class="header-anchor" href="#探测记录与-token-统计" aria-label="Permalink to &quot;探测记录与 Token 统计&quot;">​</a></h1><p>入口：<strong>运行 → 探测记录</strong>。这里查看正式探测的单次请求结果；配置草稿试探和智商测试使用各自流程，不会混入这张正式探测记录表。</p><h2 id="查找一条请求" tabindex="-1">查找一条请求 <a class="header-anchor" href="#查找一条请求" aria-label="Permalink to &quot;查找一条请求&quot;">​</a></h2><ol><li>在时间范围中选择最近 24 小时、最近 7 天、最近 30 天或全部保留记录。</li><li>选择站点；需要时进一步选择模型。</li><li>用结果筛选“成功”“偏慢”或“失败”。</li><li>打开对应记录的详情。</li></ol><p>列表支持分页。查不到刚才的结果时，先放宽时间、站点和模型筛选，再确认刚才触发的是正式探测。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/records-list.webp"><img src="'+s+'" alt="探测记录列表，包含站点模型筛选、成功偏慢失败记录和详情操作"></a></p><figcaption>① 时间、站点、模型及结果筛选；② 请求结果、耗时和详情入口。示例包含成功、偏慢及失败请求。</figcaption></figure><h2 id="阅读详情" tabindex="-1">阅读详情 <a class="header-anchor" href="#阅读详情" aria-label="Permalink to &quot;阅读详情&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信息</th><th>用途</th></tr></thead><tbody><tr><td>本次请求结果</td><td>确认这一次请求成功、偏慢还是失败</td></tr><tr><td>首 Token、总耗时</td><td>判断响应开始速度和完整请求耗时</td></tr><tr><td>当次偏慢判定依据</td><td>对照本次使用的阈值定位偏慢原因</td></tr><tr><td>输入、输出、总 Token</td><td>查看服务商明确返回的用量</td></tr><tr><td>请求端点、策略、HTTP 状态、请求 ID</td><td>确认实际连接与请求配置</td></tr><tr><td>请求详情</td><td>查看已脱敏的请求头和请求体快照</td></tr><tr><td>原始返回</td><td>查看响应头、接收数据块、错误响应及响应日志入口</td></tr></tbody></table><p>记录保存的是当次请求事实。修改当前站点配置后，历史记录不会改写为新配置。本次请求结果也与当前模型健康状态分开记录。</p><p>例如，列表出现一条“失败”，小面板仍显示“正常”，可能是尚未达到连续失败阈值；先阅读当次错误，再核对<a href="./probes.html#健康状态怎样判定">健康状态规则</a>。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/record-error.webp"><img src="'+i+'" alt="一条 HTTP 503 失败请求的详情，展示错误说明、计时、请求信息及原始返回入口"></a></p><figcaption>① 本次请求结果与计时；② 请求详情和原始返回。本例由本地演示服务返回 HTTP 503，用于展示失败排查位置。</figcaption></figure><h2 id="查看-token-统计" tabindex="-1">查看 Token 统计 <a class="header-anchor" href="#查看-token-统计" aria-label="Permalink to &quot;查看 Token 统计&quot;">​</a></h2><p>切换到“Token 统计”，按时间和站点查看汇总。</p><p>RelayPulse 只汇总服务商响应中明确上报的 <code>usage</code> 数据，不根据回答文本长度估算。未上报的值显示 <code>—</code>，不应理解为零用量。</p><p>部分字段上报时，各列仅汇总已上报的值；“平均每次”只使用已上报总 Token 的请求。因此，不同统计列的有效样本可能不同。费用以服务商账单为准。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/records-tokens.webp"><img src="'+d+'" alt="Token 统计页面中的请求数量、输入输出总 Token 和站点汇总"></a></p><figcaption>按时间和站点查看用量汇总。图中数值由本地演示服务返回，仅用于说明统计界面。</figcaption></figure><h2 id="删除与清理" tabindex="-1">删除与清理 <a class="header-anchor" href="#删除与清理" aria-label="Permalink to &quot;删除与清理&quot;">​</a></h2><ul><li>删除单条记录会删除该条正式记录及对应缓存文件，统计随之变化。</li><li>“清理全部探测记录”覆盖<strong>全部站点、全部时间范围</strong>，包含当前筛选之外的记录，同时清空对应 Token 统计。</li><li>清理正式记录不会修改当前健康状态，也不会删除站点和模型配置。</li><li>通用设置中的探测记录保留时间控制过期记录的自动清理；当前界面提供“保留 30 天”。</li></ul><p>正式响应文件可能包含模型输出内容，分享排障材料前先检查正文。诊断包与这些响应文件的范围不同，见<a href="./data.html">本地数据说明</a>。</p>',19)])])}const k=t(l,[["render",n]]);export{_ as __pageData,k as default};
